import { useEffect, useId, useRef, useSyncExternalStore } from "react";
import {
  Badge,
  Button,
  Fieldset,
  FormField,
  Heading,
  Image,
  Input,
  Price,
  ProductMedia,
  Radio,
  Select,
  Spinner,
  Stepper,
  Text,
} from "@paraxe/react";
import {
  checkoutDestination,
  checkoutScale,
  checkoutSteps,
  checkoutSubtotal,
  type Checkout01Props,
  type CheckoutValue,
} from "../shared/checkout";
import "../shared/checkout.css";
export function Checkout01({
  controller,
  title = "The finishing details.",
  description = "Good choices. A few details, and you’re on your way.",
  backHref,
  logoSrc,
}: Checkout01Props) {
  backHref = checkoutDestination(backHref);
  const id = `checkout-${useId()}`,
    state = useSyncExternalStore(
      controller.subscribe,
      controller.getSnapshot,
      controller.getSnapshot,
    ),
    { data, value, errors } = state,
    quote = controller.currentQuote(),
    scale = checkoutScale(data.currency, data.locale),
    busy = !!state.pending;
  const form = useRef<HTMLFormElement>(null),
    heading = useRef<HTMLHeadingElement>(null),
    previous = useRef(state.step);
  useEffect(() => {
    if (previous.current !== state.step) {
      heading.current?.focus();
      previous.current = state.step;
    }
  }, [state.step]);
  useEffect(() => {
    const first = Object.keys(errors)[0];
    if (first)
      form.current
        ?.querySelector<HTMLElement>(
          `[name="${first === "deliveryId" ? id + "-delivery" : first}"]`,
        )
        ?.focus();
  }, [errors, id]);
  const money = (amount: number) => (
    <Price
      amount={amount / scale}
      currency={data.currency}
      locale={data.locale}
    />
  );
  function field(
    key: Exclude<keyof CheckoutValue, "country" | "deliveryId">,
    label: string,
    autocomplete: string,
    required = true,
  ) {
    return (
      <FormField
        id={`${id}-${key}`}
        label={label}
        required={required}
        optional={!required}
        error={errors[key]}
        disabled={busy}
      >
        {(control) => (
          <Input
            {...control}
            name={key}
            autocomplete={autocomplete}
            type={key === "email" ? "email" : "text"}
            modelValue={value[key]}
            onModelValueChange={(next) => controller.edit(key, next)}
          />
        )}
      </FormField>
    );
  }
  const selected = data.deliveries.find(
      (option) => option.id === value.deliveryId,
    ),
    country = data.countries.find((country) => country.code === value.country),
    count = data.lines.reduce((sum, line) => sum + line.quantity, 0);
  return (
    <section className="checkout01" aria-labelledby={`${id}-title`}>
      <div className="checkout01-inner">
        <header className="checkout01-top">
          <div className="checkout01-brand">
            {logoSrc && <Image src={logoSrc} alt="" fit="contain" />}
            <span>{data.brand}</span>
          </div>
          <p>THE COLLECTION / CHECKOUT</p>
          {backHref && (
            <a href={backHref}>
              Back to your bag <span aria-hidden="true">↗</span>
            </a>
          )}
        </header>
        <div className="checkout01-intro">
          <div>
            <p className="checkout01-eyebrow">
              Considered from start to finish
            </p>
            <Heading level="h1" id={`${id}-title`}>
              {title}
            </Heading>
          </div>
          <Text>{description}</Text>
        </div>
        {!data.lines.length ? (
          <div className="checkout01-empty" role="status">
            <Heading level="h2">Your next essentials are waiting.</Heading>
            <Text>Add something to your bag to begin checkout.</Text>
            {backHref && <a href={backHref}>Return to your bag</a>}
          </div>
        ) : (
          <div className="checkout01-layout">
            <div className="checkout01-work">
              <a className="checkout01-summary-jump" href={`#${id}-summary`}>
                View your {count} selected {count === 1 ? "piece" : "pieces"}{" "}
                <span aria-hidden="true">&#8595;</span>
              </a>
              <Stepper
                current={controller.stepIndex()}
                steps={checkoutSteps}
                label="Checkout progress"
              />
              <form
                id={`${id}-details`}
                ref={form}
                noValidate
                onSubmit={(event) => {
                  event.preventDefault();
                  void controller.advance();
                }}
                aria-busy={busy || undefined}
              >
                <header className="checkout01-stage-heading">
                  <p className="checkout01-eyebrow">
                    0{controller.stepIndex() + 1} /{" "}
                    {checkoutSteps[controller.stepIndex()]}
                  </p>
                  <h2 ref={heading} tabIndex={-1}>
                    {state.step === "contact"
                      ? "Let’s start with you."
                      : state.step === "delivery"
                        ? "Where are we heading?"
                        : "One last look."}
                  </h2>
                  <p>
                    {state.step === "contact"
                      ? "Your contact details, for this order."
                      : state.step === "delivery"
                        ? "Choose the destination and pace that suit you."
                        : "Check your details and confirmed total before continuing."}
                  </p>
                </header>
                {state.step === "contact" && (
                  <Fieldset
                    legend="Contact details"
                    disabled={busy}
                    className="checkout01-fields"
                  >
                    <div className="checkout01-field-row">
                      {field("firstName", "First name", "given-name")}
                      {field("lastName", "Last name", "family-name")}
                    </div>
                    {field("email", "Email address", "email")}
                  </Fieldset>
                )}
                {state.step === "delivery" && (
                  <>
                    <Fieldset
                      legend="Delivery address"
                      disabled={busy}
                      className="checkout01-fields"
                    >
                      <FormField
                        id={`${id}-country`}
                        label="Country / region"
                        required
                        error={errors.country}
                        disabled={busy}
                      >
                        {(control) => (
                          <Select
                            {...control}
                            name="country"
                            modelValue={value.country}
                            onModelValueChange={(next) =>
                              controller.edit("country", next)
                            }
                          >
                            {data.countries.map((country) => (
                              <option key={country.code} value={country.code}>
                                {country.label}
                              </option>
                            ))}
                          </Select>
                        )}
                      </FormField>
                      {field(
                        "address1",
                        "Address line 1",
                        "shipping address-line1",
                      )}
                      {field(
                        "address2",
                        "Apartment, suite, etc.",
                        "shipping address-line2",
                        false,
                      )}
                      <div className="checkout01-field-row">
                        {field(
                          "city",
                          "Town / city",
                          "shipping address-level2",
                        )}
                        {field(
                          "postalCode",
                          country?.postalLabel ?? "Postal code",
                          "shipping postal-code",
                          country?.postalRequired !== false,
                        )}
                      </div>
                      {field(
                        "region",
                        "County / region",
                        "shipping address-level1",
                        false,
                      )}
                    </Fieldset>
                    <Fieldset
                      id={`${id}-delivery`}
                      legend="Choose your delivery"
                      error={errors.deliveryId}
                      disabled={busy}
                      className="checkout01-delivery"
                    >
                      <div className="checkout01-delivery-options">
                        {data.deliveries.map((option) => (
                          <Radio
                            key={option.id}
                            id={`${id}-delivery-${option.id}`}
                            name={`${id}-delivery`}
                            value={option.id}
                            modelValue={value.deliveryId}
                            disabled={busy || option.disabled}
                            required
                            invalid={!!errors.deliveryId}
                            labelledBy={`${id}-delivery-${option.id}-title ${id}-delivery-${option.id}-price`}
                            describedBy={`${id}-delivery-${option.id}-detail${errors.deliveryId ? ` ${id}-delivery-error` : ""}`}
                            onModelValueChange={(next) =>
                              controller.edit("deliveryId", String(next))
                            }
                          >
                            <span className="checkout01-delivery-top">
                              <strong id={`${id}-delivery-${option.id}-title`}>
                                {option.title}
                              </strong>
                              <span id={`${id}-delivery-${option.id}-price`}>
                                {money(option.amountMinor)}
                              </span>
                            </span>
                            <span
                              className="checkout01-delivery-detail"
                              id={`${id}-delivery-${option.id}-detail`}
                            >
                              {option.description}
                            </span>
                          </Radio>
                        ))}
                      </div>
                    </Fieldset>
                  </>
                )}
                {state.step === "review" && (
                  <div className="checkout01-review">
                    <section>
                      <div className="checkout01-review-heading">
                        <h3>Contact</h3>
                        <Button
                          variant="text"
                          size="small"
                          disabled={busy}
                          onActivate={() => controller.go("contact")}
                        >
                          Change contact
                        </Button>
                      </div>
                      <p>
                        {value.firstName} {value.lastName}
                      </p>
                      <p>{value.email}</p>
                    </section>
                    <section>
                      <div className="checkout01-review-heading">
                        <h3>Deliver to</h3>
                        <Button
                          variant="text"
                          size="small"
                          disabled={busy}
                          onActivate={() => controller.go("delivery")}
                        >
                          Change delivery
                        </Button>
                      </div>
                      <address>
                        {[
                          value.address1,
                          value.address2,
                          value.city,
                          value.region,
                          value.postalCode,
                          country?.label,
                        ]
                          .filter(Boolean)
                          .map((line, index) => (
                            <span key={index}>{line}</span>
                          ))}
                      </address>
                    </section>
                    <section>
                      <h3>Delivery method</h3>
                      <p>{selected?.title}</p>
                      <p>{selected?.description}</p>
                    </section>
                    <section className="checkout01-review-total">
                      <div>
                        <h3>Order total</h3>
                        <p>
                          {quote
                            ? "Confirmed for your delivery"
                            : "A fresh delivery quote is needed"}
                        </p>
                      </div>
                      {quote && money(quote.totalMinor)}
                    </section>
                    <div className="checkout01-review-note">
                      <span aria-hidden="true">↗</span>
                      <p>
                        {quote
                          ? "Your delivery is confirmed for this quote. Payment is the next step."
                          : "Review delivery again to refresh your quote before continuing."}
                      </p>
                    </div>
                  </div>
                )}
                {state.message && (
                  <p
                    id={`${id}-feedback`}
                    className="checkout01-feedback"
                    role={state.failed ? "alert" : "status"}
                  >
                    {state.message}
                  </p>
                )}
                <div className="checkout01-actions">
                  {state.step !== "contact" && (
                    <Button
                      variant="text"
                      disabled={busy}
                      onActivate={() =>
                        controller.go(
                          state.step === "review" ? "delivery" : "contact",
                        )
                      }
                    >
                      Back
                    </Button>
                  )}
                  <Button
                    type="submit"
                    disabled={
                      busy ||
                      state.handedOff ||
                      (state.step === "review" && !controller.canContinue)
                    }
                  >
                    {busy && <Spinner size="sm" label="" />}
                    {state.pending === "quote"
                      ? "Confirming delivery…"
                      : state.pending === "continue"
                        ? "Continuing…"
                        : state.handedOff
                          ? "Details handed over"
                          : state.step === "contact"
                            ? "Continue to delivery"
                            : state.step === "delivery"
                              ? "Review your order"
                              : controller.canContinue
                                ? "Continue to payment"
                                : "Payment unavailable"}
                    {!busy && !state.handedOff && (
                      <span aria-hidden="true">↗</span>
                    )}
                  </Button>
                </div>
                <p className="checkout01-stage-note">
                  {state.step === "review"
                    ? "Your final order is confirmed by the payment service."
                    : "Delivery availability and totals are confirmed at review."}
                </p>
              </form>
            </div>
            <aside
              className="checkout01-summary"
              aria-labelledby={`${id}-summary`}
              aria-busy={state.pending === "quote" || undefined}
            >
              <div className="checkout01-summary-heading">
                <div>
                  <p className="checkout01-eyebrow">
                    Selected for the everyday
                  </p>
                  <Heading level="h2" id={`${id}-summary`}>
                    Your selection.
                  </Heading>
                </div>
                <span>
                  {String(count).padStart(2, "0")}
                  <small>{count === 1 ? "piece" : "pieces"}</small>
                </span>
              </div>
              {data.lines.some((line) => line.imageSrc) && (
                <div className="checkout01-media-strip">
                  {data.lines.slice(0, 3).map((line) => (
                    <ProductMedia
                      key={line.id}
                      src={line.imageSrc}
                      alt={line.imageAlt}
                    />
                  ))}
                </div>
              )}
              <ol className="checkout01-lines">
                {data.lines.map((line) => (
                  <li key={line.id}>
                    <div>
                      <h3>{line.name}</h3>
                      <p>
                        {line.detail} <span>· Qty {line.quantity}</span>
                      </p>
                    </div>
                    {money(line.amountMinor)}
                  </li>
                ))}
              </ol>
              <div className="checkout01-totals">
                <dl>
                  <div>
                    <dt>Items subtotal</dt>
                    <dd>{money(checkoutSubtotal(data))}</dd>
                  </div>
                  <div>
                    <dt>Delivery</dt>
                    <dd>
                      {quote
                        ? money(quote.shippingMinor)
                        : state.pending === "quote"
                          ? "Confirming…"
                          : "At review"}
                    </dd>
                  </div>
                  {!!quote?.discountMinor && (
                    <div>
                      <dt>Discount</dt>
                      <dd>−{money(quote.discountMinor)}</dd>
                    </div>
                  )}
                  {quote?.taxMinor !== undefined && (
                    <div>
                      <dt>Tax</dt>
                      <dd>{money(quote.taxMinor)}</dd>
                    </div>
                  )}
                </dl>
                <div className="checkout01-total">
                  <div>
                    <span>Total</span>
                    <small>
                      {data.currency} /{" "}
                      {quote ? "Confirmed quote" : "Delivery pending"}
                    </small>
                  </div>
                  {quote ? (
                    money(quote.totalMinor)
                  ) : (
                    <span className="checkout01-total-pending">At review</span>
                  )}
                </div>
              </div>
              <a className="checkout01-summary-jump" href={`#${id}-details`}>
                Back to your details <span aria-hidden="true">&#8593;</span>
              </a>
              <div className="checkout01-summary-foot">
                <Badge>
                  {state.step === "review" && quote
                    ? "Ready to review"
                    : "Your order, in progress"}
                </Badge>
                <p>
                  {quote
                    ? "Review the confirmed total alongside your contact and delivery details."
                    : "Your selected pieces stay here while you complete the details."}
                </p>
              </div>
            </aside>
          </div>
        )}
        <footer className="checkout01-footer">
          <span>{data.brand}</span>
          <p>Thoughtful essentials. Everyday possibility.</p>
          <span>Contact / Delivery / Review</span>
        </footer>
      </div>
    </section>
  );
}

export type CheckoutStep = "contact" | "delivery" | "review";
export interface CheckoutLine {
  id: string;
  name: string;
  detail: string;
  quantity: number;
  amountMinor: number;
  imageSrc?: string;
  imageAlt: string;
}
export interface CheckoutCountry {
  code: string;
  label: string;
  postalRequired?: boolean;
  postalLabel?: string;
}
export interface CheckoutDelivery {
  id: string;
  title: string;
  description: string;
  amountMinor: number;
  disabled?: boolean;
}
export interface CheckoutRecord {
  id: string;
  brand: string;
  currency: string;
  locale: string;
  lines: readonly CheckoutLine[];
  countries: readonly CheckoutCountry[];
  deliveries: readonly CheckoutDelivery[];
}
export interface CheckoutValue {
  email: string;
  firstName: string;
  lastName: string;
  address1: string;
  address2: string;
  city: string;
  region: string;
  postalCode: string;
  country: string;
  deliveryId: string;
}
export type CheckoutErrors = Partial<Record<keyof CheckoutValue, string>>;
export interface CheckoutQuote {
  id: string;
  selectionKey: string;
  currency: string;
  subtotalMinor: number;
  shippingMinor: number;
  discountMinor?: number;
  taxMinor?: number;
  totalMinor: number;
  expiresAt?: string;
}
export interface CheckoutServices {
  quote: (request: {
    checkoutId: string;
    value: CheckoutValue;
    lines: CheckoutLine[];
  }) => Promise<CheckoutQuote>;
  continueCheckout?: (request: {
    checkoutId: string;
    value: CheckoutValue;
    quote: CheckoutQuote;
  }) => void | Promise<void>;
  now?: () => number;
}
export interface CheckoutSnapshot {
  data: CheckoutRecord;
  value: CheckoutValue;
  step: CheckoutStep;
  errors: CheckoutErrors;
  quote: CheckoutQuote | null;
  pending: "quote" | "continue" | null;
  message: string;
  failed: boolean;
  handedOff: boolean;
}
export const checkoutSteps = ["Contact", "Delivery", "Review"];
const stepIds: CheckoutStep[] = ["contact", "delivery", "review"];
const minor = (value: number) => Number.isSafeInteger(value) && value >= 0;
export function checkoutScale(currency: string, locale = "en-GB") {
  if (!/^[A-Z]{3}$/.test(currency))
    throw Error("Use an uppercase three-letter currency code.");
  const digits = new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
  }).resolvedOptions().maximumFractionDigits;
  if (digits === undefined) throw Error("Currency precision is unavailable.");
  return 10 ** digits;
}
export function checkoutSubtotal(data: CheckoutRecord) {
  return data.lines.reduce((sum, line) => sum + line.amountMinor, 0);
}
export function checkoutSelection(id: string, value: CheckoutValue) {
  return JSON.stringify([
    id,
    value.address1.trim(),
    value.address2.trim(),
    value.city.trim(),
    value.region.trim(),
    value.postalCode.trim(),
    value.country,
    value.deliveryId,
  ]);
}
export function validateCheckout(input: CheckoutRecord): CheckoutRecord {
  const ids = new Set<string>(),
    countries = new Set<string>(),
    deliveries = new Set<string>();
  const id = (value: string) =>
    typeof value === "string" && /^[a-zA-Z0-9][a-zA-Z0-9_-]*$/.test(value);
  if (!id(input.id) || !input.brand?.trim())
    throw Error("Checkout needs an ID and brand.");
  checkoutScale(input.currency, input.locale);
  const lines = input.lines.map((line) => {
    if (
      !id(line.id) ||
      ids.has(line.id) ||
      !line.name?.trim() ||
      !Number.isSafeInteger(line.quantity) ||
      line.quantity < 1 ||
      !minor(line.amountMinor) ||
      typeof line.imageAlt !== "string"
    )
      throw Error(
        "Checkout lines need unique IDs, names, quantities and minor-unit amounts.",
      );
    ids.add(line.id);
    return Object.freeze({ ...line });
  });
  if (!minor(lines.reduce((sum, line) => sum + line.amountMinor, 0)))
    throw Error("Checkout subtotal is too large.");
  const countryRows = input.countries.map((country) => {
    if (
      !/^[A-Z]{2}$/.test(country.code) ||
      countries.has(country.code) ||
      !country.label.trim()
    )
      throw Error("Countries need unique codes and names.");
    countries.add(country.code);
    return Object.freeze({ ...country });
  });
  const deliveryRows = input.deliveries.map((delivery) => {
    if (
      !id(delivery.id) ||
      deliveries.has(delivery.id) ||
      !delivery.title.trim() ||
      !minor(delivery.amountMinor)
    )
      throw Error("Delivery options need unique IDs and valid estimates.");
    deliveries.add(delivery.id);
    return Object.freeze({ ...delivery });
  });
  if (
    !Number.isSafeInteger(lines.reduce((sum, line) => sum + line.quantity, 0))
  )
    throw Error("Checkout quantities are too large.");
  if (lines.length && !countryRows.length)
    throw Error("An active checkout needs supported countries.");
  return Object.freeze({
    ...input,
    lines: Object.freeze(lines),
    countries: Object.freeze(countryRows),
    deliveries: Object.freeze(deliveryRows),
  });
}
export function checkoutErrors(
  data: CheckoutRecord,
  value: CheckoutValue,
  step: CheckoutStep,
): CheckoutErrors {
  const errors: CheckoutErrors = {};
  if (step === "contact" || step === "review") {
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.email.trim()))
      errors.email = "Enter a contact email address.";
    if (!value.firstName.trim()) errors.firstName = "Enter your first name.";
    if (!value.lastName.trim()) errors.lastName = "Enter your last name.";
  }
  if (step === "delivery" || step === "review") {
    if (!value.address1.trim()) errors.address1 = "Enter a delivery address.";
    if (!value.city.trim()) errors.city = "Enter your town or city.";
    const country = data.countries.find(
      (country) => country.code === value.country,
    );
    if (!country) errors.country = "Choose a supported destination.";
    if (country?.postalRequired !== false && !value.postalCode.trim())
      errors.postalCode = `Enter your ${country?.postalLabel?.toLowerCase() ?? "postal code"}.`;
    if (
      !data.deliveries.some(
        (delivery) => delivery.id === value.deliveryId && !delivery.disabled,
      )
    )
      errors.deliveryId = "Choose an available delivery method.";
  }
  return errors;
}
export function validateCheckoutQuote(
  quote: CheckoutQuote,
  data: CheckoutRecord,
  value: CheckoutValue,
  now: number,
): CheckoutQuote {
  const subtotal = checkoutSubtotal(data),
    discount = quote.discountMinor ?? 0,
    tax = quote.taxMinor ?? 0;
  if (
    !quote.id?.trim() ||
    quote.selectionKey !== checkoutSelection(data.id, value) ||
    quote.currency !== data.currency ||
    ![
      quote.subtotalMinor,
      quote.shippingMinor,
      discount,
      tax,
      quote.totalMinor,
    ].every(minor) ||
    discount > subtotal ||
    quote.subtotalMinor !== subtotal ||
    quote.totalMinor !== subtotal - discount + quote.shippingMinor + tax ||
    !Number.isSafeInteger(subtotal - discount + quote.shippingMinor + tax)
  )
    throw Error("The delivery quote no longer matches this checkout.");
  if (
    quote.expiresAt &&
    (!/T.*(?:Z|[+-]\d{2}:\d{2})$/.test(quote.expiresAt) ||
      !Number.isFinite(Date.parse(quote.expiresAt)) ||
      Date.parse(quote.expiresAt) <= now)
  )
    throw Error("The delivery quote has expired.");
  return Object.freeze({ ...quote });
}
function initialValue(
  data: CheckoutRecord,
  supplied: Partial<CheckoutValue> = {},
): CheckoutValue {
  const result = {
    email: "",
    firstName: "",
    lastName: "",
    address1: "",
    address2: "",
    city: "",
    region: "",
    postalCode: "",
    country: data.countries[0]?.code ?? "",
    deliveryId: data.deliveries.find((option) => !option.disabled)?.id ?? "",
    ...supplied,
  };
  if (Object.values(result).some((value) => typeof value !== "string"))
    throw Error("Checkout field values must be strings.");
  return Object.freeze(result);
}
export function createCheckoutController(
  input: CheckoutRecord,
  services: CheckoutServices,
  supplied: Partial<CheckoutValue> = {},
) {
  let data = validateCheckout(input),
    state: CheckoutSnapshot = {
      data,
      value: initialValue(data, supplied),
      step: "contact",
      errors: {},
      quote: null,
      pending: null,
      message: "",
      failed: false,
      handedOff: false,
    };
  let generation = 0;
  const listeners = new Set<() => void>(),
    now = services.now ?? Date.now;
  const publish = (patch: Partial<CheckoutSnapshot>) => {
    state = Object.freeze({
      ...state,
      ...patch,
      value: Object.freeze(patch.value ?? state.value),
      errors: Object.freeze(patch.errors ?? state.errors),
    });
    listeners.forEach((listener) => listener());
